package com.example.order;

import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {
    private final OrderRepository orders;
    private final StockService stock;
    private final ApplicationEventPublisher events;

    public OrderService(OrderRepository orders, StockService stock, ApplicationEventPublisher events) {
        this.orders = orders;
        this.stock = stock;
        this.events = events;
    }

    @Transactional
    public Order place(PlaceOrder command) {
        Order order = orders.save(Order.from(command));
        events.publishEvent(new OrderPlaced(order.getId(), command.email()));
        stock.reserve(command.items());
        return order;
    }
}

package com.example.order;

import org.springframework.context.event.EventListener;
import org.springframework.stereotype.Component;

@Component
public class OrderMailListener {
    private final OrderMailer mailer;

    public OrderMailListener(OrderMailer mailer) {
        this.mailer = mailer;
    }

    @EventListener
    public void on(OrderPlaced event) {
        mailer.sendConfirmation(event.email(), event.orderId());
    }
}

