package com.example.order;

import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.event.TransactionPhase;
import org.springframework.transaction.event.TransactionalEventListener;

@Component
public class OrderMailListener {
    private final OrderMailer mailer;
    private final MailLogRepository logs;

    public OrderMailListener(OrderMailer mailer, MailLogRepository logs) {
        this.mailer = mailer;
        this.logs = logs;
    }

    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    @Transactional(propagation = Propagation.REQUIRED)
    public void on(OrderPlaced event) {
        mailer.sendConfirmation(event.email(), event.orderId());
        logs.save(new MailLog(event.orderId(), event.email()));
    }
}
